import{evolutionAudio}from'./evolution-audio.js';
import {World} from './scene.js';
import {Explorer,PLACES,ROUTES,SPAWN,FORM_HEIGHTS} from './overworld.js';
import {TYPES,AREAS,STORAGE,freshJourney,freshSave,required,totalSets,maxSets,ready,unlocked,guardianReady,recordSet,winGuardian,restart,shuffle,choose,markSeen,validSave} from './core.js';
const $=s=>document.querySelector(s),esc=s=>String(s??'').replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));
let save=freshSave(),grades=[],units=[],world,screen='home',task=null,battle=null,modal=null,locked=false,soundContext=null;
let evoState=null,evoAudioStop=null;
let toastTimer,nav,lastWorldSave=0,lastNear='',frameStamp=0;
function worldState(){const j=journey();if(!j.world||typeof j.world!=='object'||Array.isArray(j.world))j.world={};let st=j.world[save.area];if(!st||typeof st!=='object')st=j.world[save.area]={player:{...SPAWN},visited:[],repaired:[],accepted:false,stamp:false};if(!Array.isArray(st.visited))st.visited=[];if(!Array.isArray(st.repaired))st.repaired=[];return st;}
function rememberPosition(){if(nav){worldState().player={...nav.player};worldState().heading=nav.heading;persist();}}
function restorePosition(){nav.setArea(save.area);nav.setLevel(journey().level);nav.restore(worldState().player);nav.heading=Number.isFinite(worldState().heading)?worldState().heading:Math.PI;save.cameraMode='follow';if(world){world.viewRig.yaw=nav.heading;world.viewRig.inputYaw=null;if(world.locomotion)world.locomotion.heading=nav.heading;}}

const typeName={match:'Word connections',sentence:'Sentence paths',qa:'Question links'};
const stationName={match:'Restore the spring',sentence:'Rebuild the wind bridge',qa:'Wake the echo shrine'};
const effectName={match:'Spring connection restored',sentence:'Bridge pathway restored',qa:'Shrine signal restored'};
function unit(){return units.find(u=>u.id===save.selected)||units[0];}
function journey(){return save.journeys[save.selected]??=(freshJourney());}
function persist(){try{localStorage.setItem(STORAGE,JSON.stringify(save));$('#save-indicator').textContent='Saved on this device';}catch{$('#save-indicator').textContent='Storage unavailable';toast('Your browser could not save. Export your journey from the journal.');}}
function toast(s){$('#toast').textContent=s;$('#toast').classList.add('toast-shown');clearTimeout(toastTimer);toastTimer=setTimeout(()=>$('#toast').classList.remove('toast-shown'),3400);}
function note(ok=true){if(save.muted)return;try{soundContext??=new (window.AudioContext||window.webkitAudioContext)();soundContext.resume();const o=soundContext.createOscillator(),g=soundContext.createGain();o.type='sine';o.frequency.setValueAtTime(ok?660:220,soundContext.currentTime);o.frequency.exponentialRampToValueAtTime(ok?990:165,soundContext.currentTime+.15);g.gain.setValueAtTime(.06,soundContext.currentTime);g.gain.exponentialRampToValueAtTime(.001,soundContext.currentTime+.25);o.connect(g).connect(soundContext.destination);o.start();o.stop(soundContext.currentTime+.26);}catch{}}
function modalShell(title,body,eyebrow='MAXIMA · YOUR JOURNEY'){modal=true;if(world){world.paused=true;world.setInput(0,0);}$('#modal-layer').innerHTML=`<div class="modal-backdrop"><section class="modal" role="dialog" aria-modal="true" aria-label="${esc(title)}"><div class="modal-header"><div><div class="eyebrow">${eyebrow}</div><h2>${title}</h2></div><button class="close" data-do="close-modal" aria-label="Close">×</button></div>${body}</section></div>`;$('.modal .close')?.focus();}
function closeModal(){modal=null;if(world)world.paused=false;$('#modal-layer').innerHTML='';}
function updateSound(){$('#sound-button').style.opacity=save.muted?'.55':'1';$('#sound-button').setAttribute('aria-label',save.muted?'Enable sound':'Mute sound');}
async function loadCreature(){try{await world.loadForm(journey().level);}catch(e){toast('The creature could not load. Please refresh with a connection.');console.error(e);}}
function home(){if(!world)return;screen='home';if(world)world.paused=false;task=null;battle=null;locked=false;$('#task-layer').innerHTML='';$('#world-labels').innerHTML='';document.body.classList.remove('playing');world.setArea(save.area);world.setView(true);renderHome();}
function renderHome(){const j=journey(),u=unit(),max=unlocked(j);save.area=Math.min(save.area,max);$('#ui').innerHTML=`<div class="home-layout"><section class="setup"><div class="eyebrow">A CREATURE’S ADVENTURE</div><h1>Your journey<br> starts here.</h1><p class="intro">Explore a vast woodland as your creature. Grow through English and awaken new forms.</p><div class="field-label"><span>Your lesson</span><span>44 unit journeys</span></div><button class="lesson-button" data-do="lessons"><span><strong>${esc(u.title)}</strong><small>GRADE ${u.grade} · ${esc(u.cefr)} · LEVEL ${j.level}${j.completed?' · COMPLETED':''}</small></span><span>↗</span></button><div class="field-label"><span>Choose your area</span><span>${max+1} / 3 unlocked</span></div><div class="area-options">${AREAS.map((a,i)=>`<button class="area-card ${i===save.area?'selected':''}" data-do="area" data-area="${i}" aria-label="${a.name}${i>max?', locked':''}" aria-pressed="${i===save.area}"><span class="area-number">0${i+1}</span>${i>max?'<span class="lock">LOCKED</span>':''}<strong>${a.name}</strong><small>${i>max?'Defeat the previous guardian':a.levels}</small></button>`).join('')}</div><div class="field-label"><span>Expedition mode</span><button class="text-button" data-do="help">How to play</button></div><div class="segmented"><button data-do="mode" data-mode="relaxed" class="${save.mode==='relaxed'?'selected':''}" aria-pressed="${save.mode==='relaxed'}">Relaxed</button><button data-do="mode" data-mode="challenge" class="${save.mode==='challenge'?'selected':''}" aria-pressed="${save.mode==='challenge'}">Challenge</button></div><p class="mode-help">${save.mode==='relaxed'?'Gentle battles, helpful clues. Take all the time you need.':'Tougher guardians, fewer hints. Reading remains untimed.'}</p><button class="primary wide" data-do="enter"><span>${j.completed?'Explore your sanctuary':totalSets(j)||j.level?'Continue adventure':'Begin your adventure'}</span><span>→</span></button><p class="quiet">Each unit has its own Level 0–10 journey.</p><button class="evo-preview-link" data-do="evolution-preview">✧ Preview transformation</button></section></div><aside class="partner-plaque"><span class="level-badge">FORM ${j.level} · AIR</span><div class="name">${esc(save.nickname)}</div><small>YOUR CREATURE · AIR</small><div class="line"></div><button data-do="rename">Name your creature</button><a class="walk-preview-link" href="partner-preview.html?level=${Math.min(3,j.level)}" target="_blank" rel="noopener">Walking previews · Levels 0–3 ↗</a></aside>`;}
function lessons(grade=unit().grade){const g=grades.find(g=>g.grade===grade);modalShell('Choose your lesson',`<p>Your creature evolves independently in every unit. Switching lessons preserves all your journeys.</p><div class="grade-tabs">${grades.map(g=>`<button data-do="grade" data-grade="${g.grade}" class="${grade===g.grade?'selected':''}">Grade ${g.grade}<small>${esc(g.cefr)}</small></button>`).join('')}</div><div class="unit-list">${g.units.map((u,i)=>{let j=save.journeys[u.id];return `<button class="unit-option ${u.id===save.selected?'selected':''}" data-do="unit" data-unit="${esc(u.id)}"><span class="num">${String(i+1).padStart(2,'0')}</span><span><strong>${esc(u.title)}</strong><small>${j?j.completed?'Journey completed · Level 10':`Level ${j.level} · ${unlocked(j)+1} area${unlocked(j)?'s':''} unlocked`:'A new journey · start at Level 0'}</small></span></button>`;}).join('')}</div>`,'LESSONS · GRADES 5–8');}
function journal(){const entries=Object.entries(save.journeys);modalShell('Journey journal',`<p>Adventures are saved in this browser. Export a backup to continue on another device.</p>${entries.map(([id,j])=>{const u=units.find(x=>x.id===id);return `<div class="journey-item"><div><strong>${esc(u.title)}</strong><small>Grade ${u.grade} · Level ${j.level} · ${j.completed?'Completed':`${totalSets(j)} / ${maxSets(j)} sets this level`}<br>${j.stats.correct} accepted answers · ${j.stats.mistakes} corrections · ${j.history.filter(x=>x.completedAt).length} completed runs</small></div><button class="secondary" data-do="journal-unit" data-unit="${esc(id)}">${id===save.selected?'Selected':'Continue'}</button></div>`;}).join('')}<div class="journal-actions"><button class="secondary" data-do="export">Export save</button><button class="secondary" data-do="import">Import save</button><button class="secondary" data-do="restart">Restart selected unit</button></div><p class="muted-note">Adventure completion records your journey. Supported answers and independent practice are tracked separately through hint use and corrections.</p>`);}
function help(){modalShell('Your first adventure',`<p>You are Hufflepuff. Walk through the woodland, follow open routes and meet other creatures. Tap the ground to move, use the left touch joystick, or press WASD / arrow keys.</p><p>The camera stays behind Hufflepuff and turns smoothly with it. Move with the left joystick and jump with the paw button or Space. Some tasks bring the camera around to show Hufflepuff’s face.</p><p>Use the region map to plan a walking route. Approach a character or landmark to interact.</p><p>Choose any unit. Every form requires all three kinds of English practice. Each practice set contains three items.</p><div class="help-grid"><div class="help-step"><b>1</b><strong>Connect words</strong><p>Tap an English terminal, then its Turkish meaning or picture. Three connections restore a spring circuit.</p></div><div class="help-step"><b>2</b><strong>Build sentences</strong><p>Tap blocks in order to guide energy across the bridge. Complete three sentences per set.</p></div><div class="help-step"><b>3</b><strong>Link questions</strong><p>Read each signal and connect the matching reply. Complete three exchanges per set.</p></div></div><p>Level 0 needs one set of each kind. Level 1 needs two, and so on. Guardians unlock the next area. Every accepted answer saves automatically.</p><p>Battle action pauses while you read. Correct work stays in place after a mistake. Tap controls work on phones, tablets and computers.</p><button class="primary wide" data-do="close-modal"><span>Ready to explore</span><span>→</span></button>`,'WELCOME TO MAXIMA');}
function enter(){screen='play';restorePosition();document.body.classList.add('playing');world.setArea(save.area);world.setView(false);renderPlay();if(!save.tutorial){save.tutorial=true;persist();help();}}
function objective(){const j=journey(),state=worldState();if(!state.accepted)return {id:'ranger',title:'A new beginning',text:'Meet Mosswing, the woodland elder.'};if(guardianReady(j)&&save.area!==unlocked(j))return{id:'camp',title:'Your next guardian',text:`Travel to ${AREAS[unlocked(j)].name} from camp for your trial.`};if(guardianReady(j))return{id:'guardian',title:'A strength worth proving',text:'Your guardian trial is ready.'};const t=TYPES.find(t=>j.sets[t]<required(j));if(!t)return{id:'ranger',title:'Keep exploring',text:'You have grown. Discover the routes.'};return{id:t,title:'Mosswing’s request',text:t==='match'?'Restore the circuits at Willow Spring.':t==='sentence'?'Repair the Old Wind Bridge.':'Read the signals at Echo Watchtower.'};}
function renderPlay(){screen='play';lastNear='';const j=journey(),a=AREAS[save.area],r=required(j),o=objective();$('#ui').innerHTML=`<div class="rpg-location"><span class="eyebrow">AREA 0${save.area+1} · ${esc(save.mode)}</span><h1>${a.name}</h1><small>${esc(unit().title)} · Grade ${unit().grade}</small></div><div class="quest-card"><small>${esc(o.title)}</small><p>${esc(o.text)}</p><button data-do="navigate" data-place="${o.id}">Follow route <span>→</span></button></div><button class="minimap" data-do="map" aria-label="Open region map"><svg viewBox="0 0 100 85" aria-hidden="true"><rect width="100" height="85" rx="10" fill="#8da780"/><path d="M54 2V83" stroke="#7dbdc2" stroke-width="7"/><path d="M8 68H89M35 68V33H18M35 33H77V12H91" fill="none" stroke="#dccb9a" stroke-width="4"/><circle cx="20" cy="65" r="7" fill="#e2d1ac"/><circle id="minimap-player" cx="20" cy="65" r="3" fill="#fff7dc" stroke="#3a6653" stroke-width="2"/></svg><span>REGION MAP ↗</span></button><div class="rpg-bottom"><button class="partner-status" data-do="training"><img src="assets/portraits/hufflepuff-${j.level}.png" alt=""><span><strong>${esc(save.nickname)} <b>Lv. ${j.level}</b></strong><small>${j.completed?'Journey complete':`${totalSets(j)*30} / ${maxSets(j)*30} XP · training journal`}</small><i><em style="width:${j.completed?100:totalSets(j)/maxSets(j)*100}%"></em></i></span></button><div class="rpg-buttons"><button data-do="help" aria-label="Controls and guide">?</button><button data-do="setup" aria-label="Open camp">Camp</button></div></div><div class="move-hint">Joystick / WASD to move · Jump / Space</div><div class="joystick" id="joystick" aria-label="Movement joystick"><div id="joystick-thumb"></div></div><button class="jump-button" id="jump-button" data-do="jump" aria-label="Jump">↑<small>JUMP</small></button><div id="context-action" class="context-action hidden"><small id="context-name"></small><button data-do="interact-near" id="context-button">Talk</button></div>`;
 $('#world-labels').innerHTML=PLACES.map(p=>`<button class="node-label ${p.kind==='guardian'?'guardian':''}" id="node-${p.id}" data-do="navigate" data-place="${p.id}"><strong>${esc(p.name)}</strong><small>${esc(p.note)}</small></button>`).join('');installJoystick();positionLabels();}
function positionLabels(){if(!world||!nav)return;world.paused=!!modal||screen!=='play'||!!task||!!battle;if(screen!=='play'||task||battle){$('#world-labels').style.display='none';return;}$('#world-labels').style.display='';const state=worldState(),now=performance.now();for(const place of PLACES){const e=$(`#node-${place.id}`);if(!e)continue;const d=Math.hypot(nav.player.x-place.x,nav.player.z-place.z),p=world.project(place.id);const show=p.visible&&d<8.5&&p.y>100&&p.y<innerHeight-135;e.style.display=show?'':'none';if(show){e.style.left=Math.max(e.offsetWidth/2+8,Math.min(innerWidth-e.offsetWidth/2-8,p.x))+'px';e.style.top=p.y+'px';}if(d<7&&!state.visited.includes(place.id)){state.visited.push(place.id);if(place.id!=='camp')toast(`Discovered ${place.name}`);}}
 const jump=$('#jump-button');if(jump)jump.disabled=nav.jumping||nav.cooldown>0||!!modal;const nearest=nav.jumping?null:nav.nearest(),context=$('#context-action');if(context){context.classList.toggle('hidden',!nearest);if(nearest&&nearest.id!==lastNear){$('#context-name').textContent=nearest.name;$('#context-button').textContent=nearest.action;}lastNear=nearest?.id||'';}
 const dot=$('#minimap-player');if(dot){dot.setAttribute('cx',Math.max(4,Math.min(96,(nav.player.x+47)/94*100)));dot.setAttribute('cy',Math.max(4,Math.min(81,(nav.player.z+39)/78*85)));}if(now-lastWorldSave>2000&&nav.moving){lastWorldSave=now;rememberPosition();}}
function installJoystick(){const pad=$('#joystick'),thumb=$('#joystick-thumb');let pointer=null;const update=e=>{const b=pad.getBoundingClientRect(),dx=e.clientX-b.left-b.width/2,dz=e.clientY-b.top-b.height/2,n=Math.max(1,Math.hypot(dx,dz)/28);world.setInput(dx/n/28,dz/n/28);thumb.style.transform=`translate(${dx/n}px,${dz/n}px)`;};pad.addEventListener('pointerdown',e=>{e.preventDefault();pointer=e.pointerId;pad.setPointerCapture(pointer);update(e);});pad.addEventListener('pointermove',e=>{if(e.pointerId===pointer)update(e);});for(const name of ['pointerup','pointercancel','lostpointercapture'])pad.addEventListener(name,()=>{pointer=null;world.setInput(0,0);thumb.style.transform='';rememberPosition();});}
function regionMap(){const pos=nav.player;modalShell(`${AREAS[save.area].name} routes`,`<p>Choose a destination to walk there. You can leave the path and explore at any time.</p><div class="region-chart"><svg viewBox="0 0 100 84" aria-hidden="true"><rect width="100" height="84" fill="#87a37a"/><path d="M54 0V84" stroke="#71b9ba" stroke-width="7"/>${ROUTES.map(r=>`<polyline points="${r.map(([x,z])=>`${(x+47)/94*100},${(z+39)/78*84}`).join(' ')}" fill="none" stroke="#d8c79c" stroke-width="3"/>`).join('')}<circle cx="${(pos.x+47)/94*100}" cy="${(pos.z+39)/78*84}" r="2" fill="#fff9df" stroke="#2f6349"/></svg>${PLACES.filter(p=>p.id!=='sign').map(p=>`<button data-do="navigate" data-place="${p.id}" style="left:${(p.x+47)/94*100}%;top:${(p.z+39)/78*100}%" aria-label="Walk to ${esc(p.name)}"><i>${p.kind==='creature'?'!':p.kind==='wild'?'✧':p.kind==='guardian'?'◇':'•'}</i><span>${esc(p.name)}</span></button>`).join('')}</div><div class="map-destinations">${PLACES.filter(p=>p.id!=='sign').map(p=>`<button class="secondary" data-do="navigate" data-place="${p.id}">${esc(p.name)}<small>${esc(p.note)}</small></button>`).join('')}</div><p class="muted-note">Your position is the white dot. Walking takes time; this map does not teleport you.</p>`,'EXPLORE · VILLAGE, ROUTES & WILDLANDS');}
function trainingJournal(){const j=journey(),r=required(j);modalShell('Your training',`<p>${esc(unit().title)} · Level ${j.level}. Complete ${r} sets of every kind to evolve. Each set contains three language items.</p><div class="training-list">${TYPES.map(t=>`<div><strong>${typeName[t]}</strong><span>${j.sets[t]} / ${r} sets</span><button class="secondary" data-do="navigate" data-place="${t}">Walk to ${t==='match'?'spring':t==='sentence'?'bridge':'watchtower'}</button></div>`).join('')}</div><p>You grow larger with every evolution.</p>${j.level>0?'<button class="secondary wide" data-do="evolution-replay-earned">Replay your latest evolution ✧</button>':''}<p class="muted-note">All your existing unit progress and guardian unlocks are preserved.</p>`);}
function interactPlace(id){if(screen!=='play'||task||battle||modal||nav.jumping)return;if(nav.nearest()?.id!==id&&Math.hypot(nav.player.x-(PLACES.find(p=>p.id===id)?.x||0),nav.player.z-(PLACES.find(p=>p.id===id)?.z||0))>3.3)return;rememberPosition();if(TYPES.includes(id)){openTask(id);return;}if(id==='guardian'){openGuardian();return;}if(id==='camp'){modalShell('Root Haven',`<p>A quiet place to plan your next route. Change your lesson, mode or unlocked region at camp.</p><button class="primary wide" data-do="setup"><span>Open camp</span><span>→</span></button>`);return;}if(id==='sign'){modalShell('Whisperwood route board',`<p><strong>West:</strong> Willow Spring and the woodland trails.</p><p><strong>East:</strong> Old Wind Bridge, the meadow and wild creatures.</p><p><strong>North-east:</strong> Echo Watchtower and the guardian gate.</p><button class="primary wide" data-do="map"><span>Look at the map</span><span>→</span></button>`);return;}if(id==='wild'){modalShell('A creature in the meadow',`<p>You spot a Bramble Sprite in the tall grass. It answers your call with a curious rustle.</p><p>Prepare one move through English to complete a friendly training encounter. It can count toward a practice set you still need.</p><button class="primary wide" data-do="wild"><span>Begin the encounter</span><span>→</span></button>`,'WILD ENCOUNTER · BRAMBLE SPRITE');return;}if(id==='ranger'){const state=worldState(),helped=state.repaired.length===3;modalShell('Mosswing',!state.accepted?`<p>“Welcome, little one. This woodland is full of paths waiting for your paws.”</p><p>“The spring, bridge and watchtower need your help. Follow any route you like. Your knowledge will help the forest—and help you grow.”</p><button class="primary wide" data-do="accept-quest"><span>I’ll help the woodland</span><span>→</span></button>`:helped?`<p>“You’ve helped all three places! This field journal stamp is yours. Keep learning—the guardian is watching your strength grow.”</p><div class="village-stamp">WILLOWBROOK HELPER<br><small>Recorded in your journey</small></div>`:`<p>“Explore at your own pace. The spring is west, the bridge crosses the river, and the watchtower is beyond the meadow.”</p><p>${state.repaired.length} / 3 places helped in this region.</p><button class="primary wide" data-do="map"><span>Show the routes</span><span>→</span></button>`,'WILLOWBROOK · WOODLAND ELDER');if(helped){state.stamp=true;persist();}}}
function startWild(){closeModal();battle={wild:true,hp:100,enemy:100,round:0,action:null,phase:'choice',pattern:['recover'],enemyName:'Bramble Sprite'};world.setView(false,null,true);$('#world-labels').style.display='none';$('#ui').innerHTML='';renderBattleChoice();}
function selectItems(type){const u=unit(),j=journey();if(type==='match'){const list=choose(u.vocabulary,u.vocabulary.length,j.seen),items=[];for(const x of list)if(!items.some(y=>y.en===x.en||y.tr===x.tr)){items.push(x);if(items.length===3)break;}return items;}if(type==='sentence')return choose(u.sentences,3,j.seen);return choose(u.questions,3,j.seen);}
function openTask(type,fromBattle=false){if(locked)return;const j=journey();if(!fromBattle&&j.completed){toast('This journey is complete. Choose a new lesson or restart from the journal.');return;}if(!fromBattle&&j.sets[type]>=required(j)){toast('This practice is ready. Complete the other kinds to evolve.');return;}if(!fromBattle&&(j.pending?.[type]||j.active?.type===type))task=j.pending?.[type]||j.active;else{const items=selectItems(type);task={type,items,left:shuffle([0,1,2]),right:shuffle([0,1,2]),paired:[],selected:null,step:0,used:[],blockOrder:shuffle(items[0]?.blocks?.map((_,i)=>i)||[]),choices:shuffle(items[0]?.options||[]),hint:false,hinted:[],mistakes:0,battle:fromBattle};if(type==='match'&&Math.random()<.4&&items.every(x=>x.picture)&&new Set(items.map(x=>x.picture)).size===3&&new Set(items.map(x=>x.pictureGroup||x.picture)).size===3)task.picture=true;}
 if(!fromBattle){j.active=task;persist();}world.setView(false,type,fromBattle);$('#world-labels').style.display='none';renderTask();if(task.type==='match'&&task.paired.length===3)finishSet();else if(task.type==='sentence'&&task.used.length===task.items[task.step].blocks.length)stepComplete();}
function dots(count=0){return `<div class="set-dots" aria-label="${count} of 3 complete">${[0,1,2].map(i=>`<i class="${i<count?'on':''}"></i>`).join('')}</div>`;}
function taskShell(body){const t=task;const count=t.type==='match'?t.paired.length:t.step;return `<div class="task-wrap"><section class="task-panel" role="region" aria-label="${esc(typeName[t.type])}"><div class="task-header"><div><div class="eyebrow">${battle?`${battle.wild?'WILD ENCOUNTER':'GUARDIAN TRIAL'} · ${battle.round+1} / ${battle.wild?1:3}`:`${esc(AREAS[save.area].name)} · SET ${journey().sets[t.type]+1} / ${required(journey())}`}</div><h2>${battle?battle.action==='guard'?'Form a wind barrier':battle.action==='disrupt'?'Break the charge':'Shape your wind strike':stationName[t.type]}</h2></div><button class="close" data-do="close-task" aria-label="Save and return to exploration">×</button></div><p class="task-instruction">${t.type==='match'?`Tap an English terminal, then its ${t.picture?'picture':'Turkish meaning'}. Each pair powers the circuit.`:t.type==='sentence'?'Tap the sentence blocks in order. Every connection builds the pathway.':'Read the incoming signal. Choose the reply that answers it.'}</p>${body}<div class="task-footer"><div><p class="feedback" id="feedback" aria-live="polite">${t.hint?hintText():'Correct work stays connected.'}</p>${dots(count)}</div><button class="hint-button" data-do="hint">${save.mode==='challenge'&&!t.mistakes?'Try first · then hint':'Need a hint?'}</button></div></section></div>`;}
function renderTask(){if(!task)return;let body='';const t=task;
 if(t.type==='match'){body=`<div class="matching-board"><svg class="connection-svg" aria-hidden="true"></svg><div class="matching-col">${t.left.map(i=>`<button class="terminal ${t.paired.includes(i)?'paired':''} ${t.selected===i?'selected':''}" data-do="match-left" data-index="${i}" ${t.paired.includes(i)?'disabled':''}>${esc(t.items[i].en)}</button>`).join('')}</div><div class="wire-space"><span>◇</span><span>◇</span><span>◇</span></div><div class="matching-col">${t.right.map(i=>`<button class="terminal ${t.paired.includes(i)?'paired':''}" data-do="match-right" data-index="${i}" ${t.paired.includes(i)?'disabled':''}>${t.picture?`<img src="${esc(t.items[i].picture)}" alt="${esc(t.items[i].en)}">`:esc(t.items[i].tr)}</button>`).join('')}</div></div>`;}
 else if(t.type==='sentence'){const item=t.items[t.step];body=`<div class="sentence-target ${t.used.length?'':'empty'}" aria-label="Sentence pathway">${t.used.length?t.used.map(i=>`<button disabled>${esc(item.blocks[i])}</button>`).join(''):'Your sentence will guide the wind'}</div><div class="sentence-source">${t.blockOrder.map(i=>`<button class="word-block ${t.used.includes(i)?'used':''}" data-do="block" data-index="${i}" draggable="true">${esc(item.blocks[i])}</button>`).join('')}</div>${t.hint&&item.tr?`<div class="translation" lang="tr">${esc(item.tr)}</div>`:''}`;}
 else{const item=t.items[t.step];body=`<div class="question-bubble">${esc(item.prompt)}</div><div class="reply-list">${t.choices.map((s,i)=>`<button class="reply" data-do="reply" data-index="${i}">${esc(s)}</button>`).join('')}</div>`;}
 world.progress(t.type,t.type==='match'?t.paired.length/3:t.type==='sentence'?(t.step+t.used.length/t.items[t.step].blocks.length)/3:t.step/3);$('#task-layer').innerHTML=taskShell(body);if(t.type==='match')requestAnimationFrame(drawWires);persistTask();}
function drawWires(){if(task?.type!=='match')return;const board=$('.matching-board'),svg=$('.connection-svg');if(!board||!svg)return;const b=board.getBoundingClientRect();svg.setAttribute('viewBox',`0 0 ${b.width} ${b.height}`);svg.innerHTML=task.paired.map(i=>{let l=$(`[data-do="match-left"][data-index="${i}"]`).getBoundingClientRect(),r=$(`[data-do="match-right"][data-index="${i}"]`).getBoundingClientRect();let x1=l.right-b.left,y1=l.top+l.height/2-b.top,x2=r.left-b.left,y2=r.top+r.height/2-b.top;return `<path d="M${x1},${y1} C${x1+35},${y1} ${x2-35},${y2} ${x2},${y2}"/>`;}).join('');}
function persistTask(){if(task&&!battle){journey().active=task;(journey().pending??={})[task.type]=task;}persist();}
function feedback(s,state=''){const e=$('#feedback');if(e){e.textContent=s;e.className='feedback '+state;}}
function wrong(){if(!task)return;task.mistakes++;journey().stats.mistakes++;note(false);feedback('That connection does not fit. Read it again, or ask for a hint.','error');if(battle){battle.hp=Math.max(0,battle.hp-(save.mode==='challenge'?12:5));renderBattleHUD();if(battle.hp===0){loseBattle();return;}}persistTask();}
function correct(){journey().stats.correct++;note();world.celebrate(task.type);persistTask();}
function hintText(){if(!task)return '';if(task.type==='sentence')return `Next part: ${task.items[task.step].blocks[task.used.length]||'sentence complete'}`;if(task.type==='match'){const i=task.selected??task.left.find(i=>!task.paired.includes(i));return `${task.items[i].en} → ${task.items[i].tr}`;}return `Look for a reply about ${task.items[task.step].prompt.split(' ').slice(0,3).join(' ')}…`;}
function hint(){if(!task||locked)return;if(save.mode==='challenge'&&!task.mistakes){feedback('Make an independent attempt first. A hint unlocks after a correction.');return;}const key=task.type==='match'?task.selected??task.left.find(i=>!task.paired.includes(i)):task.step;if(!task.hinted.includes(key)){task.hinted.push(key);journey().stats.hints++;}task.hint=true;if(task.type==='qa'){feedback(`Matching reply: ${task.items[task.step].answer}`);persistTask();}else{renderTask();feedback(hintText());}}
async function stepComplete(){locked=true;const oldTask=task;markSeen(journey(),[oldTask.items[oldTask.step]]);feedback('Signal connected. The forest responds.','success');await delay(650);if(task!==oldTask){locked=false;return;}oldTask.step++;oldTask.used=[];oldTask.hint=false;locked=false;if(oldTask.step===3){finishSet();return;}oldTask.blockOrder=shuffle(oldTask.items[oldTask.step].blocks?.map((_,i)=>i)||[]);oldTask.choices=shuffle(oldTask.items[oldTask.step].options||[]);renderTask();}
function delay(n){return new Promise(r=>setTimeout(r,n));}
async function finishSet(){locked=true;const type=task.type;world.progress(type,1);if(type==='match')markSeen(journey(),task.items);if(battle){await battleMove();return;}journey().active=null;if(journey().pending)delete journey().pending[type];const state=worldState();if(!state.repaired.includes(type))state.repaired.push(type);const result=recordSet(journey(),type);persist();$('#task-layer').innerHTML=`<div class="task-wrap"><section class="task-panel"><div class="eyebrow">${esc(typeName[type])} · SET COMPLETE</div><div class="task-complete"><span class="seal">✧</span><div><h3>${effectName[type]}</h3><p>Three language items completed. Your power grows stronger.</p></div></div><button class="primary wide" data-do="return-world"><span>${result.evolved?'Meet your next form':result.guardian?'Your guardian trial is ready':'Return to the valley'}</span><span>→</span></button></section></div>`;task={type,finished:true,evolved:result.evolved};world.celebrate(type);locked=false;}
async function returnWorld(){const evolved=task?.evolved;task=null;battle=null;$('#task-layer').innerHTML='';world.setView(false);if(evolved){await evolution();}else renderPlay();}
function startEvolutionSound(){evoAudioStop?.();evoAudioStop=null;if(save.muted)return;try{soundContext??=new(window.AudioContext||window.webkitAudioContext)();soundContext.resume();evoAudioStop=evolutionAudio(soundContext,world.evolution?.time||0);}catch{}}
async function evolution(final=false,options={}){
 const returnTo=options.returnTo||(screen==='home'?'home':'play'),level=journey().level,to=options.to??(options.demo?Math.min(10,level+1):level),from=options.from??(final?to:options.demo?level:Math.max(0,to-1));
 closeModal();evoState={final,demo:!!options.demo,returnTo,from,to,loading:true,skip:false};const state=evoState;screen='evolution';locked=true;modal='evolution';task=null;battle=null;persist();$('#task-layer').innerHTML='';$('#ui').innerHTML='';$('#world-labels').innerHTML='';document.body.classList.add('cinematic');world.setView(false);world.paused=true;
 $('#modal-layer').innerHTML=`<section class="evo-cinematic" aria-label="Hufflepuff transformation"><div class="evo-top"><span>${state.demo?'TRANSFORMATION PREVIEW':'MAXIMA · AIR AWAKENING'}</span><div><button data-do="evolution-sound" id="evo-sound" aria-label="Toggle transformation sound">${save.muted?'Sound off':'Sound on'}</button><button data-do="evolution-skip" id="evo-skip">Skip</button></div></div><div class="evo-loading" id="evo-loading">Gathering the wind…</div><div class="evo-caption" id="evo-caption" role="status" aria-live="polite"></div><div class="evo-finish hidden" id="evo-finish"></div></section>`;
 try{
  if(!save.muted){try{soundContext??=new(window.AudioContext||window.webkitAudioContext)();soundContext.resume();}catch{}}
  const playing=world.playEvolution(from,to,{reduced:matchMedia('(prefers-reduced-motion: reduce)').matches,onFrame:f=>{if(state!==evoState)return;const loading=$('#evo-loading');if(loading&&!loading.classList.contains('hidden')){state.loading=false;loading.classList.add('hidden');startEvolutionSound();if(state.skip)queueMicrotask(()=>world.skipEvolution());}const caption=$('#evo-caption');if(caption&&state.phase!==f.phase){state.phase=f.phase;caption.textContent=f.phase==='spark'?'A spark awakens.':f.phase==='gather'?'The wind answers.':f.phase==='orbit'?'Your knowledge becomes strength.':f.phase==='transform'?(final?'Your journey becomes legend.':'A new form takes shape.'):'';}}});
  await playing;if(state!==evoState)return;evoAudioStop?.();evoAudioStop=null;locked=false;$('#evo-skip').classList.add('hidden');$('#evo-caption').textContent='';const finish=$('#evo-finish');finish.classList.remove('hidden');finish.innerHTML=`<div class="eyebrow">${state.demo?'PREVIEW · JOURNEY UNCHANGED':final?'UNIT JOURNEY COMPLETE':'YOUR NEXT FORM AWAKENS'}</div><h1>${final?'An extraordinary journey.':`Form ${to} awakened.`}</h1><p>${esc(save.nickname)} · AIR</p><div class="evo-result-actions"><button class="secondary" data-do="evolution-replay">Replay ↻</button><button class="primary" data-do="evolution-continue"><span>${state.demo?'Back to adventure':final||unlocked(journey())>save.area?'Continue to camp':'Continue adventure'}</span><span>→</span></button></div>`;
 }catch(error){console.error(error);evoAudioStop?.();world.endEvolution(false);locked=false;state.failed=true;$('#evo-loading').textContent='The new model could not load. Your earned progress is saved.';$('#evo-caption').innerHTML='<button class="secondary" data-do="evolution-replay">Retry reveal</button> <button class="primary" data-do="evolution-continue">Return to camp</button>';$('#evo-skip').classList.add('hidden');}
}
async function finishEvolution(){const state=evoState;if(!state||locked)return;world.endEvolution(!state.demo&&!state.failed);evoState=null;evoAudioStop?.();evoAudioStop=null;document.body.classList.remove('cinematic');closeModal();world.paused=false;$('#modal-layer').innerHTML='';if(state.failed)await loadCreature();if(state.returnTo==='home'||state.failed||journey().completed||unlocked(journey())>save.area){if(!state.demo)save.area=unlocked(journey());restorePosition();persist();home();}else{world.setView(false);screen='play';renderPlay();}}
function openGuardian(){const j=journey();if(j.guardians.includes(save.area)){toast('This guardian has been overcome. Continue training or choose the next area at camp.');return;}if(!guardianReady(j)||save.area!==unlocked(j)){modalShell('A strength worth proving',`<p>${AREAS[save.area].guardian} watches over this area. Complete your training before the trial.</p><p>Guardians appear after training at Levels 2, 5 and 10. Every required practice category must be complete.</p><button class="primary wide" data-do="close-modal"><span>Return to training</span><span>→</span></button>`);return;}battle={hp:100,enemy:100,round:0,action:null,phase:'choice',pattern:shuffle(['charge','guard','recover'])};world.setView(false,null,true);$('#world-labels').style.display='none';$('#ui').innerHTML='';renderBattleChoice();}
function renderBattleHUD(){if(!battle)return;let hud=$('#battle-hud');if(!hud){hud=document.createElement('div');hud.id='battle-hud';hud.className='battle-hud';$('#ui').append(hud);}hud.innerHTML=`<div class="combatant"><strong>${esc(save.nickname)}</strong><small>FORM ${journey().level} · ${battle.hp} / 100 HP</small><div class="hp"><i style="width:${battle.hp}%"></i></div></div><div class="combatant enemy"><strong>${battle.enemyName||AREAS[save.area].guardian}</strong><small>${battle.enemy} / 100 HP · PHASE ${Math.min(battle.wild?1:3,battle.round+1)}</small><div class="hp"><i style="width:${battle.enemy}%"></i></div></div>`;}
function renderBattleChoice(){task=null;locked=false;battle.phase='choice';renderBattleHUD();const p=battle.pattern[battle.round];const tells={charge:'The guardian draws energy into its core. A powerful strike is coming.',guard:'The guardian raises its armour. Its energy connections are exposed.',recover:'The guardian lowers its arms to recover. You have an opening.'};$('#task-layer').innerHTML=`<div class="task-wrap"><section class="task-panel"><div class="task-header"><div><div class="eyebrow">${battle.wild?'WILD ENCOUNTER':'GUARDIAN TRIAL'} · CHOOSE YOUR MOVE</div><h2>${battle.wild?'You step forward.':'Read the guardian.'}</h2></div><button class="close" data-do="close-task" aria-label="Retreat from guardian">×</button></div><p class="task-instruction">${battle.wild?'The Bramble Sprite waits for your move.':tells[p]} Combat pauses while you prepare your move.</p><div class="battle-choice">${[{id:'attack',name:'Strike',symbol:'↗',desc:'Sentence paths · exploit an opening',best:p==='recover'},{id:'guard',name:'Guard',symbol:'◇',desc:'Question links · absorb a charge',best:p==='charge'},{id:'disrupt',name:'Disrupt',symbol:'⌁',desc:'Word connections · break its armour',best:p==='guard'}].map(a=>`<button class="ability ${save.mode==='relaxed'&&a.best?'recommended':''}" data-do="ability" data-action="${a.id}"><span class="sigil">${a.symbol}</span><strong>${a.name}</strong><small>${a.desc}</small>${save.mode==='relaxed'&&a.best?'<small>Recommended</small>':''}</button>`).join('')}</div><p class="feedback">${battle.wild?'One prepared move completes this encounter.':'Three prepared moves complete the trial.'} Mistakes cost ${save.mode==='relaxed'?5:12} HP.</p></section></div>`;}
async function battleMove(){const current=battle;if(!current)return;current.lastType=task.type;const p=current.pattern[current.round],best=(p==='charge'&&current.action==='guard')||(p==='guard'&&current.action==='disrupt')||(p==='recover'&&current.action==='attack');const cost=best?0:save.mode==='challenge'?20:10;current.hp=Math.max(0,current.hp-cost);current.enemy=Math.max(0,100-Math.round((current.round+1)*100/(current.wild?1:3)));current.round++;task=null;world.hit();renderBattleHUD();$('#task-layer').innerHTML=`<div class="task-wrap"><section class="task-panel battle-result"><div class="eyebrow">${best?'PERFECTLY READ':'MOVE COMPLETE'}</div><h3>${current.action==='guard'?'The wind holds.':current.action==='disrupt'?'Its charge breaks.':'Your strike connects.'}</h3><p class="feedback">${best?'Your decision protected you.':`The guardian counters. You lose ${cost} HP.`}</p></section></div>`;persist();await delay(1600);if(battle!==current)return;if(current.hp<=0){loseBattle();return;}if(current.round>=(current.wild?1:3)){winBattle();return;}locked=false;renderBattleChoice();}
async function winBattle(){if(battle.wild){const type=battle.lastType,result=recordSet(journey(),type);persist();task={type,finished:true,evolved:result.evolved};battle=null;locked=false;$('#ui').innerHTML='';$('#task-layer').innerHTML=`<div class="task-wrap"><section class="task-panel battle-result"><div class="eyebrow">FRIENDLY ENCOUNTER COMPLETE</div><h3>A new understanding.</h3><p class="feedback">${result.changed?'Your completed English set strengthens your creature.':'This practice category is already complete for this level.'}</p><button class="primary wide" data-do="return-world"><span>${result.evolved?'Meet your next form':'Return to the meadow'}</span><span>→</span></button></section></div>`;return;}winGuardian(journey());persist();task=null;battle=null;locked=false;$('#task-layer').innerHTML='';$('#ui').innerHTML='';world.setView(false);await evolution(journey().completed);}
function loseBattle(){task=null;locked=false;$('#task-layer').innerHTML=`<div class="task-wrap"><section class="task-panel battle-result"><div class="eyebrow">A CHANCE TO LEARN</div><h3>Rest. Reconnect. Return.</h3><p class="feedback">Your training and XP are safe. Try the guardian again, or choose Relaxed at camp.</p><button class="primary wide" data-do="return-world"><span>Return to training</span><span>→</span></button></section></div>`;}
function exportSave(){persist();const blob=new Blob([JSON.stringify(save,null,2)],{type:'application/json'}),url=URL.createObjectURL(blob),a=document.createElement('a');a.href=url;a.download='Maxima-Journey-Backup.json';a.click();setTimeout(()=>URL.revokeObjectURL(url),1000);toast('Journey backup exported.');}
function importSave(){const input=document.createElement('input');input.type='file';input.accept='.json,application/json';input.onchange=async()=>{try{if(input.files[0].size>8_000_000)throw Error('too large');const next=JSON.parse(await input.files[0].text());if(!validSave(next,units))throw Error('invalid');for(const j of Object.values(next.journeys)){j.active=null;j.pending={};}save=next;save.area=Math.max(0,Math.min(Number(save.area)||0,unlocked(journey())));persist();closeModal();loadCreature();home();toast('Journey restored.');}catch{toast('This file is not a valid Maxima journey backup.');}};input.click();}
async function act(e){const b=e.target.closest('[data-do]');if(!b||b.disabled)return;const d=b.dataset;if(screen==='evolution'&&!['evolution-skip','evolution-continue','evolution-replay','evolution-sound'].includes(d.do))return;switch(d.do){
 case 'lessons':lessons();break;case 'grade':lessons(Number(d.grade));break;
 case 'unit':case 'journal-unit':rememberPosition();save.selected=d.unit;save.grade=unit().grade;save.area=unlocked(journey());persist();closeModal();restorePosition();loadCreature();home();break;
 case 'area':{const i=Number(d.area);if(i>unlocked(journey())){toast(`Defeat ${AREAS[i-1].guardian} to unlock ${AREAS[i].name}.`);break;}rememberPosition();save.area=i;restorePosition();persist();world.setArea(i);renderHome();break;}
 case 'mode':save.mode=d.mode;persist();renderHome();break;
 case 'navigate':{const id=d.place;closeModal();world.walkTo(id);toast(`Walking to ${PLACES.find(p=>p.id===id)?.name||id}. Tap anywhere to change your route.`);break;}
 case 'jump':world.jump();break;case 'map':regionMap();break;case 'training':trainingJournal();break;case 'interact-near':if(nav.nearest())interactPlace(nav.nearest().id);break;case 'accept-quest':worldState().accepted=true;persist();closeModal();renderPlay();toast('Mosswing’s request added. Choose your own route.');break;case 'wild':startWild();break;case 'zoom':world.zoom=Math.max(.8,Math.min(1.5,world.zoom+Number(d.zoom)*.15));break;
 case 'enter':enter();break;case 'setup':rememberPosition();closeModal();if(task?.battle||battle)toast('The guardian trial resets when you retreat. Your training stays saved.');home();break;
 case 'help':help();break;case 'close-modal':closeModal();break;
 case 'rename':modalShell('Name your creature',`<p>A name for all your unit adventures.</p><input class="input" id="nickname" maxlength="24" value="${esc(save.nickname)}" aria-label="Creature nickname"><button class="primary wide" data-do="save-name"><span>Make it yours</span><span>→</span></button>`);$('#nickname').focus();break;
 case 'save-name':save.nickname=$('#nickname').value.trim().slice(0,24)||'Hufflepuff';persist();closeModal();renderHome();break;
 case 'node':world.walkTo(d.type);break;case 'guardian':world.walkTo('guardian');break;
 case 'close-task':if(locked)return;if(battle){battle=null;toast('You retreated. Training progress is safe.');}task=null;$('#task-layer').innerHTML='';world.setView(false);renderPlay();persist();break;
 case 'match-left':if(locked||!task||task.finished)return;task.selected=Number(d.index);renderTask();break;
 case 'match-right':{if(locked||task?.selected==null)return;const i=Number(d.index);if(i!==task.selected){wrong();break;}task.paired.push(i);task.selected=null;correct();renderTask();feedback('Connection accepted. The spring gains energy.','success');if(task.paired.length===3){locked=true;await delay(550);if(task?.type==='match'&&!task.finished)finishSet();}break;}
 case 'block':{if(locked||!task||task.finished)return;const i=Number(d.index),item=task.items[task.step];if(task.used.includes(i))return;if(item.blocks[i]!==item.blocks[task.used.length]){wrong();break;}task.used.push(i);correct();renderTask();if(task.used.length===item.blocks.length)stepComplete();break;}
 case 'reply':{if(locked||!task||task.finished)return;const i=Number(d.index);if(task.choices[i]!==task.items[task.step].answer){wrong();break;}correct();b.classList.add('correct');stepComplete();break;}
 case 'hint':hint();break;case 'return-world':returnWorld();break;
 case 'ability':if(!battle||locked)return;battle.action=d.action;openTask(d.action==='attack'?'sentence':d.action==='guard'?'qa':'match',true);renderBattleHUD();break;
 case 'evolution-preview':await evolution(false,{demo:true,returnTo:'home'});break;
 case 'evolution-replay-earned':closeModal();await evolution(false,{returnTo:'play'});break;
 case 'evolution-skip':if(evoState){evoState.skip=true;world.skipEvolution();}break;
 case 'evolution-sound':save.muted=!save.muted;persist();updateSound();$('#evo-sound').textContent=save.muted?'Sound off':'Sound on';startEvolutionSound();break;
 case 'evolution-replay':if(evoState&&!locked){const options={...evoState};world.endEvolution(!options.demo&&!options.failed);await evolution(options.final,options);}break;
 case 'evolution-continue':await finishEvolution();break;
 case 'export':exportSave();break;case 'import':importSave();break;
 case 'restart':modalShell('Begin a fresh journey?',`<p>Restart <strong>${esc(unit().title)}</strong> at Level 0. Current XP and area unlocks reset; completed runs remain in your journal. Your other units are preserved.</p><button class="primary wide" data-do="confirm-restart"><span>Restart this unit</span><span>→</span></button>`);break;
 case 'confirm-restart':save.journeys[save.selected]=restart(journey());save.area=0;restorePosition();persist();closeModal();loadCreature();home();toast('Your Level 0 adventure begins.');break;
 }}
document.addEventListener('click',e=>{act(e).catch(err=>{console.error(err);locked=false;toast('Something interrupted this action. Your saved training is safe.');});});
$('#home-button').onclick=()=>{if(locked||!world)return;rememberPosition();closeModal();home();};$('#journal-button').onclick=()=>{if(!locked)journal();};$('#sound-button').onclick=()=>{save.muted=!save.muted;persist();updateSound();note();};
document.addEventListener('keydown',e=>{if(e.key==='Escape'){if(modal==='evolution')return;if(modal)closeModal();else if(task&&!locked)$('[data-do="close-task"]')?.click();}});
document.addEventListener('contextmenu',e=>{if(e.target.closest('.task-panel, #world'))e.preventDefault();});
let draggedIndex=null;document.addEventListener('dragstart',e=>{const b=e.target.closest('[data-do="block"]');if(b&&!locked){draggedIndex=b.dataset.index;e.dataTransfer.setData('text/plain',draggedIndex);}else e.preventDefault();});document.addEventListener('dragover',e=>{if(e.target.closest('.sentence-target'))e.preventDefault();});document.addEventListener('drop',e=>{if(e.target.closest('.sentence-target')){e.preventDefault();const b=$(`[data-do="block"][data-index="${draggedIndex}"]`);b?.click();draggedIndex=null;}});
window.addEventListener('resize',()=>{if(task?.type==='match')requestAnimationFrame(drawWires);});document.addEventListener('visibilitychange',()=>{if(document.hidden){world?.setInput(0,0);rememberPosition();evoAudioStop?.();evoAudioStop=null;}else if(evoState&&!evoState.loading&&world.evolution&&!world.evolution.resolved)startEvolutionSound();});
async function boot(){try{const data=await fetch('data/units.json').then(r=>{if(!r.ok)throw Error('Language pack missing');return r.json();});grades=data.grades;units=grades.flatMap(g=>g.units.map(u=>({...u,grade:g.grade,cefr:g.cefr})));try{const raw=localStorage.getItem(STORAGE);if(raw){const candidate=JSON.parse(raw);if(validSave(candidate,units))save=candidate;}}catch{toast('A fresh journey is ready. Import a backup if needed.');}save.area=Math.min(save.area,unlocked(journey()));nav=new Explorer(id=>interactPlace(id));restorePosition();world=new World($('#world'),interactPlace,nav);world.onFrame=positionLabels;await loadCreature();home();updateSound();$('#load-note').classList.add('hidden');}catch(e){console.error(e);$('#load-note').classList.add('hidden');$('#ui').innerHTML=`<section class="error-box"><div class="eyebrow">MAXIMA</div><h1>3D graphics could not start.</h1><p>Maxima uses a fully 3D world and requires WebGL. This browser could not provide a 3D graphics context. Try opening the game directly in a current browser with graphics acceleration available.</p><p>Your saved unit journeys are preserved.</p><button class="primary" onclick="location.reload()">Retry 3D</button></section>`;}}
boot();
